// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    address owner = address(0x1);
    address acc1 = address(0x2);
    address acc2 = address(0x3);

    function setUp() public {
        vm.prank(owner);
        c = new ERCDDAToken(1000, "Test", "TST");
        vm.prank(owner);
        c.mintToken(acc1, 500);
        vm.prank(owner);
        c.mintToken(acc2, 300);
    }

    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerBal = c.balanceOf(owner);
        vm.assume(burnAmount > 0 && burnAmount <= ownerBal);

        uint256 preBal0 = c.balanceOf(owner);
        uint256 preBal1 = c.balanceOf(acc1);
        uint256 preBal2 = c.balanceOf(acc2);
        uint256 preTotalSupply = c.totalSupply();

        vm.prank(owner);
        c.burn(burnAmount);

        uint256 postBal0 = c.balanceOf(owner);
        uint256 postBal1 = c.balanceOf(acc1);
        uint256 postBal2 = c.balanceOf(acc2);
        uint256 postTotalSupply = c.totalSupply();
        uint256 sumBalances = postBal0 + postBal1 + postBal2;

        assertTrue(sumBalances <= postTotalSupply);
    }
}
